args.new_string:
interface UserProfileData {
  name: string
  email: string
}

async function getUserProfile(): Promise<UserProfileData | null> {
  try {
    const res = await fetch('/api/users/profile')
    if (!res.ok) return null
    return await res.json()
  } catch {
    return null
  }
}

export default async function UserProfile() {
  const user = await getUserProfile()

  if (!user) return <div>User profile unavailable</div>

  return (
    <div>
      <h2>User profile</h2>
      <div>{user.name}</div>
      <div>{user.email}</div>
    </div>
  )
}

